/* ==========================================================================
   Nixora Services LLC — form endpoint (single-file build).

   Generated by worker/scripts/bundle.js from src/email.js, src/forms.js and
   src/index.js. Do not edit this file: edit those and rebuild, or the next
   build will overwrite whatever was changed here.

   This is the file to paste into the Cloudflare dashboard editor when
   deploying without a terminal. See worker/README.md.
   ========================================================================== */

/* ==========================================================================
   Nixora Services LLC — notification email rendering.

   Tables and inline styles only: Gmail and Outlook strip <style> blocks,
   flexbox and grid. 600px is the width every client renders without
   horizontal scrolling, and the logo is a hosted PNG because most clients
   refuse to draw SVG.
   ========================================================================== */

const NAVY = '#054a8b';
const INK = '#0e1626';
const MUTED = '#5d6b82';
const LINE = '#eef2f7';
const TINT = '#f4f7fb';
const LIME = '#57741b';

function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/* Turns a typed phone number into a dialable href. US numbers arrive as
   (314) 555-0000; anything already carrying a + is left alone. */
function telHref(phone) {
  const raw = String(phone || '').trim();
  if (!raw) return '';
  if (raw.charAt(0) === '+') return raw.replace(/[^\d+]/g, '');
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  return digits.length === 10 ? '+1' + digits : '+' + digits;
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

/* Formats the YYYY-MM-DD that <input type="date"> submits. Parsed by hand
   rather than through Date, which would shift the day across time zones. */
function formatDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || '').trim());
  if (!match) return String(value || '');
  const month = MONTHS[Number(match[2]) - 1];
  if (!month) return value;
  return month + ' ' + Number(match[3]) + ', ' + match[1];
}

const label = (text) =>
  `<p style="margin:0 0 10px;font-size:12px;font-weight:700;letter-spacing:1.3px;` +
  `text-transform:uppercase;color:${NAVY};">${escapeHtml(text)}</p>`;

const cell = (style) =>
  `padding:9px 0;border-bottom:1px solid ${LINE};${style || ''}`;

/* A label/value table. `html` is already-escaped markup so a value can carry
   a link or a line break. */
function rowsTable(rows) {
  const body = rows.map(([name, html]) =>
    `<tr><td style="${cell('width:180px;color:' + MUTED + ';')}">${escapeHtml(name)}</td>` +
    `<td style="${cell()}">${html}</td></tr>`
  ).join('');

  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="font-size:15px;color:${INK};border-collapse:collapse;">${body}</table>`;
}

/* Ticked declarations. The tick is an entity rather than an emoji so it keeps
   its colour, and the sentence still reads if a client drops the glyph. */
function checksTable(items) {
  const last = items.length - 1;
  const body = items.map((item, i) => {
    const pad = i === 0 ? '14px 16px 4px'
      : i === last ? '4px 16px 14px'
        : '4px 16px';
    return `<tr><td style="padding:${pad};">` +
      `<span style="color:${LIME};font-weight:700;">&#10003;</span>&nbsp; ${escapeHtml(item)}</td></tr>`;
  }).join('');

  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="font-size:14px;color:#33425c;background-color:${TINT};border-radius:10px;">${body}</table>`;
}

function messageBlock(text) {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="background-color:${TINT};border-radius:10px;">
    <tr><td style="padding:16px;font-size:15px;line-height:1.6;color:${INK};">
      ${escapeHtml(text).replace(/\r?\n/g, '<br>')}
    </td></tr></table>`;
}

function section(block) {
  let inner = '';
  if (block.rows) inner = rowsTable(block.rows);
  else if (block.checks) inner = checksTable(block.checks);
  else if (block.text) inner = messageBlock(block.text);
  else return '';

  return `<tr><td style="padding:26px 32px 0;">${label(block.title)}${inner}</td></tr>`;
}

function buttons(actions) {
  if (!actions.length) return '';
  const html = actions.map((action, i) => {
    const style = i === 0
      ? `display:inline-block;background-color:${NAVY};color:#ffffff;text-decoration:none;` +
        `font-size:15px;font-weight:700;padding:12px 22px;border-radius:100px;`
      : `display:inline-block;margin-left:8px;color:${NAVY};text-decoration:none;` +
        `font-size:15px;font-weight:700;padding:12px 18px;border:1.5px solid #dee4ee;border-radius:100px;`;
    return `<a href="${escapeHtml(action.href)}" style="${style}">${escapeHtml(action.text)}</a>`;
  }).join('\n              ');

  return `<p style="margin:18px 0 0;">\n              ${html}\n            </p>`;
}

/**
 * Renders the notification body.
 *
 * spec: { eyebrow, title, subtitle, actions[], sections[], signature, footer,
 *         siteUrl, logoUrl }
 */
function renderEmail(spec) {
  const sections = (spec.sections || []).map(section).join('\n');

  // Without a signature block the last section would sit flush against the
  // footer, so an empty row supplies the missing bottom margin.
  const spacer = spec.signature
    ? ''
    : `<tr><td style="height:30px;line-height:30px;font-size:0;">&nbsp;</td></tr>`;

  const signature = spec.signature
    ? `<tr><td style="padding:22px 32px 30px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
                 style="border-top:2px solid ${LINE};">
            <tr><td style="padding:16px 0 0;font-size:14px;color:${MUTED};">
              Signed electronically by
              <strong style="color:${INK};">${escapeHtml(spec.signature.name)}</strong>
              on ${escapeHtml(formatDate(spec.signature.date))}
            </td></tr>
          </table>
        </td></tr>`
    : '';

  return `<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(spec.eyebrow)}</title></head>
<body style="margin:0;padding:0;background-color:${LINE};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
       style="margin:0;padding:0;background-color:#eef2f7;">
  <tr>
    <td align="center" style="padding:24px 12px;">

      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"
             style="width:600px;max-width:100%;background-color:#ffffff;border-radius:12px;overflow:hidden;
                    font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">

        <!-- Header. The alt text is styled white so it still reads on the
             navy band in clients that block images by default. -->
        <tr>
          <td style="background-color:${NAVY};padding:26px 32px;">
            <img src="${escapeHtml(spec.logoUrl)}" width="150" height="73" alt="Nixora Services"
                 style="display:block;border:0;outline:none;text-decoration:none;height:auto;
                        color:#ffffff;font-family:Arial,Helvetica,sans-serif;font-size:20px;
                        font-weight:700;">
            <p style="margin:16px 0 0;font-size:13px;line-height:1.4;color:#b3d2ef;
                      letter-spacing:1.4px;text-transform:uppercase;font-weight:700;">
              ${escapeHtml(spec.eyebrow)}
            </p>
          </td>
        </tr>

        <tr>
          <td style="padding:30px 32px 8px;">
            <h1 style="margin:0 0 6px;font-size:26px;line-height:1.25;color:${INK};font-weight:700;">
              ${escapeHtml(spec.title)}
            </h1>
            <p style="margin:0;font-size:16px;line-height:1.5;color:${MUTED};">
              ${spec.subtitle}
            </p>
            ${buttons(spec.actions || [])}
          </td>
        </tr>

${sections}
${signature}${spacer}

        <tr>
          <td style="background-color:${TINT};padding:18px 32px;font-size:12px;line-height:1.6;color:${MUTED};">
            ${spec.footer}
          </td>
        </tr>

      </table>
    </td>
  </tr>
</table>
</body></html>`;
}

/* Plain-text alternative. Every notification ships with one: it is what
   deliverability filters look for, and what a watch or a screen reader gets. */
function renderText(spec) {
  const lines = [spec.eyebrow.toUpperCase(), '', spec.title, spec.subtitleText, ''];

  (spec.sections || []).forEach((block) => {
    lines.push(block.title.toUpperCase());
    if (block.rows) block.rows.forEach(([name, , plain]) => lines.push('  ' + name + ': ' + plain));
    else if (block.checks) block.checks.forEach((item) => lines.push('  [x] ' + item));
    else if (block.text) lines.push('  ' + block.text.replace(/\r?\n/g, '\n  '));
    lines.push('');
  });

  if (spec.signature) {
    lines.push('Signed electronically by ' + spec.signature.name +
      ' on ' + formatDate(spec.signature.date), '');
  }

  lines.push(spec.footerText);
  return lines.join('\n');
}

/* ==========================================================================
   Nixora Services LLC — turning a submitted form into a notification.

   One module per concern: this one knows the field names used by the site's
   three forms, email.js knows how to draw them, index.js moves the request.
   ========================================================================== */

/* Field names as they appear in the HTML. Kept here so a rename on the site
   is a one-line change rather than a hunt through the renderer. */
const A = {
  position: 'Position Applied For',
  name: 'Full Name',
  email: 'email',
  phone: 'Phone',
  dob: 'Date of Birth',
  street: 'Street Address',
  city: 'City',
  state: 'State',
  zip: 'ZIP Code',
  ecName: 'Emergency Contact',
  ecPhone: 'Emergency Phone',
  ecRelation: 'Emergency Relationship',
  experience: 'Cleaning Experience',
  availability: 'Availability',
  shifts: 'Shifts Available',
  notes: 'Experience Notes',
  resume: 'Resume Link',
  signature: 'Electronic Signature',
  signedOn: 'Signed On'
};

const DECLARATIONS = [
  ['Certified Accurate', 'Certified the information is accurate'],
  ['Accepted SMS and WhatsApp', 'Accepted SMS and WhatsApp updates'],
  ['Accepted Digital Data Handling', 'Accepted digital handling of their data'],
  ['Accepted Background and Drug Screening', 'Accepted background check and drug screening']
];

/* Reads a form value, trimmed, never undefined. */
const get = (form, key) => String(form.get(key) || '').trim();

const firstName = (full) => String(full || '').trim().split(/\s+/)[0] || 'the applicant';

const mailLink = (address) =>
  `<a href="mailto:${escapeHtml(address)}" style="color:#054a8b;">${escapeHtml(address)}</a>`;

const urlLink = (href) =>
  `<a href="${escapeHtml(href)}" style="color:#054a8b;">${escapeHtml(href)}</a>`;

/* Drops rows whose value came back empty, so an optional field the applicant
   skipped leaves no blank line in the email. */
const rows = (list) => list.filter(([, , plain]) => plain);

const textRow = (name, value) => [name, escapeHtml(value), value];

const STARS = (rating) => {
  const n = Math.max(0, Math.min(5, Number(rating) || 0));
  return '★'.repeat(n) + '☆'.repeat(5 - n);
};

/* ------------------------------------------------------------------ */

function applicationSpec(form) {
  const name = get(form, A.name);
  const email = get(form, A.email);
  const phone = get(form, A.phone);
  const position = get(form, A.position);

  const cityLine = [get(form, A.city), get(form, A.state)].filter(Boolean).join(', ');
  const address = [get(form, A.street), [cityLine, get(form, A.zip)].filter(Boolean).join(' ')]
    .filter(Boolean);

  const emergency = [get(form, A.ecName), get(form, A.ecPhone)].filter(Boolean).join(' · ');
  const relation = get(form, A.ecRelation);

  const schedule = [get(form, A.availability), get(form, A.shifts)]
    .filter(Boolean).join(' · ');

  const actions = [];
  if (email) actions.push({ href: 'mailto:' + email, text: 'Reply to ' + firstName(name) });
  if (telHref(phone)) actions.push({ href: 'tel:' + telHref(phone), text: phone });

  const checks = DECLARATIONS
    .filter(([field]) => get(form, field))
    .map(([, sentence]) => sentence);

  const sections = [
    {
      title: 'Applicant',
      rows: rows([
        ['Email', email ? mailLink(email) : '', email],
        textRow('Date of birth', formatDate(get(form, A.dob))),
        ['Address', address.map(escapeHtml).join('<br>'), address.join(', ')],
        ['Emergency contact',
          escapeHtml(emergency) + (relation ? ` <span style="color:#5d6b82;">(${escapeHtml(relation)})</span>` : ''),
          emergency + (relation ? ' (' + relation + ')' : '')]
      ])
    },
    {
      title: 'Availability',
      rows: rows([
        textRow('Experience', get(form, A.experience)),
        textRow('Schedule', schedule),
        textRow('Notes', get(form, A.notes)),
        ['Resume', get(form, A.resume) ? urlLink(get(form, A.resume)) : '', get(form, A.resume)]
      ])
    }
  ];

  if (checks.length) sections.push({ title: 'Declarations', checks });

  const signatureName = get(form, A.signature);

  return {
    subject: position ? `${name} applied — ${position}` : `${name} applied`,
    replyTo: email,
    eyebrow: 'New job application',
    title: name,
    subtitle: `applied for <strong style="color:#054a8b;">${escapeHtml(position)}</strong>`,
    subtitleText: 'applied for ' + position,
    actions,
    sections,
    signature: signatureName
      ? { name: signatureName, date: get(form, A.signedOn) }
      : null,
    page: 'apply.html',
    formName: 'application form',
    footerNote: 'Replying to this email goes straight to the applicant.'
  };
}

function contactSpec(form) {
  const name = get(form, 'name');
  const email = get(form, 'email');
  const phone = get(form, 'Phone');
  const service = get(form, 'Service Needed');
  const company = get(form, 'Company');

  const actions = [];
  if (email) actions.push({ href: 'mailto:' + email, text: 'Reply to ' + firstName(name) });
  if (telHref(phone)) actions.push({ href: 'tel:' + telHref(phone), text: phone });

  return {
    subject: `${name} — new service request`,
    replyTo: email,
    eyebrow: 'New service request',
    title: name,
    subtitle: service
      ? `is asking about <strong style="color:#054a8b;">${escapeHtml(service)}</strong>`
      : 'wrote in through the contact form',
    subtitleText: service ? 'is asking about ' + service : 'wrote in through the contact form',
    actions,
    sections: [
      {
        title: 'Contact',
        rows: rows([
          ['Email', email ? mailLink(email) : '', email],
          textRow('Phone', phone),
          textRow('Company', company),
          textRow('Service needed', service)
        ])
      },
      { title: 'Message', text: get(form, 'Message') }
    ],
    signature: null,
    page: '#contact',
    formName: 'contact form',
    footerNote: 'Replying to this email goes straight to the sender.'
  };
}

function reviewSpec(form) {
  const name = get(form, 'name');
  const rating = get(form, 'Rating');
  const type = get(form, 'Reviewer Type');
  const consent = get(form, 'Consented To Publish');

  return {
    subject: `${name} left a ${rating}-star review`,
    replyTo: '',
    eyebrow: 'New website review',
    title: name,
    subtitle: `left a <strong style="color:#054a8b;">${escapeHtml(rating)}-star review</strong> ` +
      `<span style="color:#d9922c;">${STARS(rating)}</span>`,
    subtitleText: 'left a ' + rating + '-star review',
    actions: [],
    sections: [
      {
        title: 'Reviewer',
        rows: rows([
          textRow('Name', name),
          textRow('Reviewer type', type),
          textRow('Rating', rating ? rating + ' of 5  ' + STARS(rating) : '')
        ])
      },
      { title: 'Review', text: get(form, 'Message') },
      {
        title: 'Permission',
        checks: [consent
          ? 'Allowed Nixora Services to publish this review with their first name and role'
          : 'Did NOT allow this review to be published — keep it internal']
      }
    ],
    signature: null,
    page: '#feedback',
    formName: 'feedback form',
    footerNote: 'The reviewer did not leave an email address, so this thread cannot be replied to.'
  };
}

const BUILDERS = {
  application: applicationSpec,
  contact: contactSpec,
  review: reviewSpec
};

/* Trusts the hidden _form field, and works out the type from the fields
   themselves when it is missing — a submission should never be lost to a
   markup slip. */
function detectFormType(form) {
  const declared = get(form, '_form').toLowerCase();
  if (BUILDERS[declared]) return declared;
  if (form.get(A.position)) return 'application';
  if (form.get('Rating')) return 'review';
  return 'contact';
}

function buildSpec(form, type) {
  const build = BUILDERS[type] || contactSpec;
  const spec = build(form);

  // A submission with no name would produce an empty subject line, so fall
  // back to something an inbox can still sort on.
  if (!spec.title) {
    spec.title = 'Website submission';
    spec.subject = spec.eyebrow + ' — Nixora Services';
  }
  return spec;
}

/* ==========================================================================
   Nixora Services LLC — form endpoint.

   Receives the three site forms, renders a branded notification and hands it
   to Resend. It replaces Formspree so the subject line, the layout and the
   sending address all belong to Nixora rather than to a third party.

   Configuration lives in wrangler.toml ([vars]); the Resend key is a secret:
     npx wrangler secret put RESEND_API_KEY
   ========================================================================== */

const RESEND_ENDPOINT = 'https://api.resend.com/emails';

// A job application with long notes is a few kilobytes. Anything past this is
// not a person filling in a form.
const MAX_BODY_BYTES = 128 * 1024;

const json = (body, status, headers) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...headers }
  });

function allowedOrigins(env) {
  return String(env.ALLOWED_ORIGINS || '')
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean);
}

/* Echoes the origin back only when it is on the list. An unknown origin gets
   no CORS header at all, so the browser blocks the response. */
function corsHeaders(request, env) {
  const origin = request.headers.get('Origin');
  const headers = { 'vary': 'Origin' };
  if (origin && allowedOrigins(env).indexOf(origin) !== -1) {
    headers['access-control-allow-origin'] = origin;
    headers['access-control-allow-methods'] = 'POST, OPTIONS';
    headers['access-control-allow-headers'] = 'Content-Type, Accept';
    headers['access-control-max-age'] = '86400';
  }
  return headers;
}

/* The site posts with fetch and asks for JSON. A browser that fell back to a
   plain form POST gets sent to the thank-you page instead. */
const wantsJson = (request) =>
  String(request.headers.get('Accept') || '').indexOf('application/json') !== -1;

function recipient(env, type) {
  const perForm = {
    application: env.TO_APPLICATIONS,
    contact: env.TO_CONTACT,
    review: env.TO_REVIEWS
  }[type];
  return String(perForm || env.TO_EMAIL || '').trim();
}

async function readForm(request) {
  const contentType = String(request.headers.get('Content-Type') || '');
  if (contentType.indexOf('application/json') !== -1) {
    const body = await request.json();
    const form = new FormData();
    Object.keys(body || {}).forEach((key) => form.append(key, String(body[key])));
    return form;
  }
  return request.formData();
}

async function send(env, { to, replyTo, subject, html, text }) {
  const payload = {
    from: env.FROM_EMAIL,
    to: [to],
    subject,
    html,
    text
  };
  if (replyTo) payload.reply_to = replyTo;

  const response = await fetch(RESEND_ENDPOINT, {
    method: 'POST',
    headers: {
      authorization: 'Bearer ' + env.RESEND_API_KEY,
      'content-type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const detail = await response.text();
    throw new Error('Resend responded ' + response.status + ': ' + detail);
  }
  return response.json();
}

export default {
  async fetch(request, env) {
    const cors = corsHeaders(request, env);

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: cors });
    }

    if (request.method !== 'POST') {
      return json({ ok: false, error: 'Send this form with POST.' }, 405, cors);
    }

    const origin = request.headers.get('Origin');
    if (origin && allowedOrigins(env).indexOf(origin) === -1) {
      return json({ ok: false, error: 'Origin not allowed.' }, 403, cors);
    }

    const declaredLength = Number(request.headers.get('Content-Length') || 0);
    if (declaredLength > MAX_BODY_BYTES) {
      return json({ ok: false, error: 'Submission too large.' }, 413, cors);
    }

    let form;
    try {
      form = await readForm(request);
    } catch (error) {
      return json({ ok: false, error: 'Could not read the submission.' }, 400, cors);
    }

    // Honeypot: bots fill in every field they find, people never see this one.
    // Answering 200 keeps them from working out that they were caught.
    if (String(form.get('_gotcha') || '').trim()) {
      return wantsJson(request)
        ? json({ ok: true }, 200, cors)
        : Response.redirect(env.SITE_URL + '/thank-you.html', 303);
    }

    const type = detectFormType(form);
    const to = recipient(env, type);
    if (!to || !env.FROM_EMAIL || !env.RESEND_API_KEY) {
      console.error('Worker is missing TO_EMAIL, FROM_EMAIL or RESEND_API_KEY.');
      return json({ ok: false, error: 'The form endpoint is not configured.' }, 500, cors);
    }

    const spec = buildSpec(form, type);
    const siteUrl = String(env.SITE_URL || 'https://www.nixoraservices.com').replace(/\/$/, '');
    const pageUrl = siteUrl + '/' + spec.page;

    spec.logoUrl = siteUrl + '/assets/img/mail-logo.png';
    spec.footer = `Sent from the ${escapeHtml(spec.formName)} at ` +
      `<a href="${escapeHtml(pageUrl)}" style="color:#054a8b;">nixoraservices.com</a>. ` +
      escapeHtml(spec.footerNote);
    spec.footerText = 'Sent from the ' + spec.formName + ' at ' + pageUrl + '. ' + spec.footerNote;

    try {
      await send(env, {
        to,
        replyTo: spec.replyTo,
        subject: spec.subject,
        html: renderEmail(spec),
        text: renderText(spec)
      });
    } catch (error) {
      console.error('Sending failed:', error && error.message);
      return json({ ok: false, error: 'The message could not be sent.' }, 502, cors);
    }

    return wantsJson(request)
      ? json({ ok: true }, 200, cors)
      : Response.redirect(siteUrl + '/thank-you.html', 303);
  }
};
